const sl=me.txs.filter(t=>t.mode=='shop'&&t.t=='in'),ca=sl.reduce((a,t)=>a+t.a,0),inv=me.txs.filter(t=>t.mode=='fee'||t.mode=='stock').reduce((a,t)=>a+t.a,0),pf=ca-inv;
