function pat(x,p,tc){x.globalAlpha=.1;x.strokeStyle=tc;x.fillStyle=tc;x.lineWidth=2;if(p=='waves')for(let i=0;i<28;i++){x.beginPath();x.ellipse(800,160,50+i*28,30+i*18,i*.1,0,7);x.stroke()}else if(p=='grid'){for(let i=0;i<1100;i+=48){x.beginPath();x.moveTo(i,0);x.lineTo(i,644);x.stroke()}for(let j=0;j<700;j+=48){x.beginPath();x.moveTo(0,j);x.lineTo(1024,j);x.stroke()}}else if(p=='dots'){for(let i=0;i<1024;i+=32)for(let j=0;j<644;j+=32){x.beginPath();x.arc(i,j,4,0,7);x.fill()}}else if(p=='stripes'){for(let i=-700;i<1100;i+=36){x.beginPath();x.moveTo(i,644);x.lineTo(i+644,0);x.stroke()}}x.globalAlpha=1}
